INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_eng_s3_032', 'topic_wassce_english_summary', 'subj_wassce_english', 'exam_wassce', NULL, NULL, 'Combine the following into one summary sentence without losing the essential meaning: "The bridge was old. Heavy lorries crossed it daily. It finally collapsed in August."', 'short_answer', NULL, NULL, 'Because the old bridge carried heavy lorries daily, it finally collapsed in August.', 'The three statements form a cause chain: age plus daily heavy loads led to the August collapse; link all three facts with "because" (or a similar connector) and add nothing.', 'medium', '4', '2', '90', NULL, NULL, '1', NULL, NULL, 'Summarize', 'AO2', NULL, NULL, NULL);
